mapper.select:
SELECT COUNT(1) AS TOT_CNT FROM tb_product_reviews A WHERE 1 = 1
AND A.DISPLAY_YN = 'Y'
AND A.PRODUCT_ID = #{productId}

SELECT A.REVIEW_ID, A.PRODUCT_ID, A.ORDER_ID, A.USER_NO, A.RATING, A.CONTENTS, A.ATCH_DOC_ID, A.DISPLAY_YN, DATE_FORMAT(A.REGIST_DT, '%Y.%m.%d') AS REGIST_DT, U.USER_NM, P.TITLE AS PRODUCT_NM, (SELECT GROUP_CONCAT(CONCAT(FILE_PARTN_COURS, FILE_ID, '.', FILE_EXTSN_NM) ORDER BY SORT_ORDR) FROM tb_file WHERE DOC_ID = A.ATCH_DOC_ID) AS FILE_PATHS FROM tb_product_reviews A INNER JOIN op_user U ON A.USER_NO = U.USER_NO INNER JOIN tb_product P ON A.PRODUCT_ID = P.PRODUCT_ID WHERE 1 = 1
AND A.DISPLAY_YN = 'Y'
AND A.PRODUCT_ID = #{productId}
ORDER BY A.REGIST_DT DESC
LIMIT #{limitStart}, #{limitEnd}

mapper.update:
UPDATE tb_product_reviews SET RATING = #{rating}, CONTENTS = #{contents},
ATCH_DOC_ID = #{atchDocId},
UPDUSR_NO = #{ss_user_no}, UPDT_DT = CURRENT_TIMESTAMP WHERE REVIEW_ID = #{reviewId} AND USER_NO = #{ss_user_no}

UPDATE tb_product_reviews
SET DISPLAY_YN = 'N',
    UPDUSR_NO = #{ss_user_no},
    UPDT_DT = CURRENT_TIMESTAMP
WHERE REVIEW_ID = #{reviewId}

    AND USER_NO = #{ss_user_no}
